#include <bits/stdc++.h>
using namespace std;

int n;

void printBase(int value, string& output) {
    if (value >= n) printBase(value / n, output);
    output.push_back(char('0' + value % n));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    string output;

    for (int i = 1; i < n; ++i) {
        for (int j = 1; j < n; ++j) {
            printBase(i * j, output);
            output += (j < n - 1 ? ' ' : '\n');
        }
    }

    cout << output;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

string toBase(int value, int base) {
    string result;
    do {
        result.push_back(char('0' + value % base));
        value /= base;
    } while (value > 0);
    reverse(result.begin(), result.end());
    return result;
}

